from pathlib import Path
import re

p = Path("index.html")
s = p.read_text(encoding="utf-8")

new_auth = r'''function auth(){document.getElementById("app").innerHTML='<div class="auth"><div class="hero"><div class="eyebrow" style="color:#8fc1ff">Rotina clínica organizada</div><h1>Presenças e faltas sem várias planilhas.</h1><p>Cadastre pacientes uma vez, registre cada atendimento e acompanhe o histórico automaticamente.</p></div><div class="side"><div class="card login"><div class="eyebrow">Acesso restrito</div><h2 id="at">Entrar na plataforma</h2><p id="ad">Use seu nome de usuário e senha.</p><div id="am"></div><div class="field"><label>Usuário</label><input id="username" class="input" type="text" autocomplete="username" maxlength="32" placeholder="admin"></div><div class="field"><label>Senha</label><input id="pass" class="input" type="password" autocomplete="current-password" minlength="12"></div><div class="field hidden" id="af"><label>Código de ativação</label><input id="activation" class="input" type="password" autocomplete="off" placeholder="Código de uso único"></div><button id="go" class="btn primary full">Entrar</button><div class="links" style="justify-content:center"><button id="activate" class="link">Ativar primeiro administrador</button></div></div></div></div>';var mode="login";function setMode(next){mode=next;var activating=mode==="activate";$("#at").textContent=activating?"Ativar administrador":"Entrar na plataforma";$("#ad").textContent=activating?"Defina a senha do administrador. O código de ativação funciona uma única vez.":"Use seu nome de usuário e senha.";$("#go").textContent=activating?"Ativar administrador":"Entrar";$("#af").classList.toggle("hidden",!activating);$("#activate").textContent=activating?"Voltar ao login":"Ativar primeiro administrador";$("#username").disabled=activating;if(activating)$("#username").value="admin"}$("#activate").onclick=function(){setMode(mode==="activate"?"login":"activate")};$("#go").onclick=async function(){var username=$("#username").value.trim().toLowerCase(),pass=$("#pass").value,activation=$("#activation").value.trim();if(!username||!pass){msg("#am","Informe usuário e senha.",false);return}if(!/^[a-z0-9._-]{3,32}$/.test(username)){msg("#am","Usuário inválido.",false);return}if(pass.length<12){msg("#am","A senha precisa ter pelo menos 12 caracteres.",false);return}if(mode==="activate"&&!activation){msg("#am","Informe o código de ativação.",false);return}try{var payload=mode==="activate"?{action:"bootstrap",username:username,password:pass,secret:activation}:{action:"login",username:username,password:pass};var r=await fetch(SB+"/functions/v1/username-auth",{method:"POST",headers:{"apikey":KEY,"Content-Type":"application/json"},body:JSON.stringify(payload)});var j=await r.json();if(!r.ok)throw new Error(j.error||"Falha no acesso");if(!j.session)throw new Error("Sessão não recebida.");save(j.session);boot()}catch(x){msg("#am",x.message,false)}}}'''

s, n = re.subn(r'function auth\(\)\{.*?\}\nfunction onboarding', new_auth + '\nfunction onboarding', s, count=1, flags=re.S)
if n != 1:
    raise SystemExit("auth block not found")

s = s.replace("'+e(S.user.email||\"\")+'<br>'+e(S.member.role)+'", "'+e((S.user.user_metadata&&S.user.user_metadata.username)||\"admin\")+'<br>'+e(S.member.role)+'")

p.write_text(s, encoding="utf-8")
